import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder):
        return {
            'success': False,
            'message': 'Source folder does not exist',
            'failed_files': []
        }

    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)

    file_paths = glob(os.path.join(src_folder, '*'))
    file_paths = [f for f in file_paths if os.path.isfile(f)]

    failed_files = []
    success = True

    for file_path in file_paths:
        filename = os.path.basename(file_path)
        try:
            proc = subprocess.Popen(['gzip', file_path])
            proc.wait()
            if proc.returncode != 0:
                failed_files.append(filename)
                success = False
            else:
                gz_file_path = file_path + '.gz'
                shutil.move(gz_file_path, os.path.join(dst_folder, filename + '.gz'))
        except Exception:
            failed_files.append(filename)
            success = False

    if success:
        message = 'All files compressed and moved successfully'
    else:
        message = 'Some files failed to compress or move'

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

