import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")

    start_time = time.time()
    end_time = start_time + duration
    log_data = []
    system = platform.system()

    while time.time() < end_time:
        timestamp = time.time()
        cpu_usage = 0.0
        try:
            if system == "Windows":
                output = subprocess.check_output('wmic cpu get loadpercentage', shell=True)
                lines = output.decode().split('\n')
                for line in lines:
                    if line.strip().isdigit():
                        cpu_usage = float(line.strip())
                        break
            else:
                output = subprocess.check_output("top -bn1 | grep 'Cpu(s)'", shell=True)
                parts = output.decode().split(',')
                for part in parts:
                    if 'id' in part:
                        idle = float(part.split()[0])
                        cpu_usage = 100.0 - idle
                        break
        except Exception:
            cpu_usage = 0.0

        log_data.append({'timestamp': timestamp, 'cpu_usage': cpu_usage})
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(log_data, f)
        return LOGFILE_PATH
    except IOError:
        return None

